"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["63410"],{99779(e){e.exports=JSON.parse('{"id":"F359","slug":"underwriting-economics","name":"IPO Underwriting Spread and Greenshoe","subject":"Banking & Financial Institutions","section":"Banking","topic":"Investment banking: advisory, underwriting, trading","level":"Beginner","aliases":["investment banking","underwriting fees","gross spread","overallotment option","money left on the table"],"formula":{"latex":"\\\\text{Gross spread}=s\\\\,P\\\\,N,\\\\quad \\\\text{Net proceeds}=PN(1-s)-\\\\text{Costs},\\\\quad \\\\text{Left on table}=(P_{1}-P)N","also":[],"text":"Gross spread = spread % x offer price x shares; Net proceeds to the issuer = price x shares x (1 - spread %) - other costs; Greenshoe adds up to 15% more shares if demand is strong; Money left on the table = (first-day close - offer price) x shares sold"},"symbols":[{"symbol":"P","meaning":"Offer price","unit":"money"},{"symbol":"N","meaning":"Shares sold in the base deal","unit":"millions"},{"symbol":"s","meaning":"Gross spread: the underwriters\' fee as a share of proceeds","unit":"percent"},{"symbol":"P_1","meaning":"Price at the end of the first day of trading","unit":"money"}],"when_to_use":"Use it to see what an offering costs the issuer and what the banks earn. The spread pays for advisory work, risk-taking by the underwriters and selling to investors. The greenshoe lets the banks sell extra shares and cover them from the issuer if the price rises, or from the market if it falls, which supports the price. First-day pops show underpricing, a cost to the issuer.","worked_example":{"problem":"An IPO sells 50 million shares at 20 with a 5% spread, 3 million of other costs and a greenshoe of 15%. The shares close at 23.60 on the first day.","inputs":{"n":50,"p":20,"s":5,"cost":3,"gsh":15,"p1":23.6},"steps":[{"label":"Gross proceeds = P x N","working":"20 x 50","value":"1,000.00"},{"label":"Underwriting spread = s x gross","working":"0.05 x 1000","value":"50.00"},{"label":"Net proceeds to the issuer","working":"1000-50-3","value":"947.00"},{"label":"Extra net proceeds if the greenshoe is fully used","working":"0.15 x 50 x 20 x (1-0.05)","value":"142.50"},{"label":"First-day return","working":"23.6 / 20-1","value":"18.0%"},{"label":"Money left on the table = (P1 - P) x N","working":"(23.6-20) x 50","value":"180.00"}],"answer":"The base deal raises 1,000.00 and the underwriters earn 50.00, leaving the issuer 947.00 after other costs. If the greenshoe is fully used, 7.5 million more shares add 142.50 of net proceeds. The first-day gain of 18.0% left 180.00 on the table."},"calculator":{"available":true,"inputs":[{"id":"n","label":"Shares sold (millions)","unit":"millions","type":"number","default":50,"hint":""},{"id":"p","label":"Offer price","unit":"money","type":"number","default":20,"hint":""},{"id":"s","label":"Gross spread","unit":"%","type":"number","default":5,"hint":""},{"id":"cost","label":"Other offering costs (millions)","unit":"money","type":"number","default":3,"hint":""},{"id":"gsh","label":"Greenshoe size","unit":"%","type":"number","default":15,"hint":""},{"id":"p1","label":"First-day closing price","unit":"money","type":"number","default":23.6,"hint":""}],"checks":[{"expr":"n>0 and p>0 and s<1","message":"Shares and price must be above zero and the spread below 100%."}],"steps":[{"id":"gross","label":"Gross proceeds = P x N","expr":"p*n","format":"money"},{"id":"fee","label":"Underwriting spread = s x gross","expr":"s*gross","format":"money"},{"id":"net","label":"Net proceeds to the issuer","expr":"gross-fee-cost","format":"money"},{"id":"gadd","label":"Extra net proceeds if the greenshoe is fully used","expr":"gsh*n*p*(1-s)","format":"money"},{"id":"pop","label":"First-day return","expr":"p1/p-1","format":"pct1"},{"id":"left","label":"Money left on the table = (P1 - P) x N","expr":"(p1-p)*n","format":"money"}],"results":["gross","fee","net","left"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"gross":1000,"fee":50,"net":947,"gadd":142.5,"pop":0.18,"left":180.00000000000006}},"finder":{"finds":"What an offering raises and costs","needs":"Shares, price, spread, costs, greenshoe, first-day price"},"related":[{"slug":"ipo-underpricing","name":"IPO Underpricing (Initial Return)"},{"slug":"vc-post-money","name":"Pre-Money and Post-Money Valuation"},{"slug":"dilution-from-new-issue","name":"Ownership Dilution from a New Share Issue"}],"related_ids":["F184","F182","F186"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Gross\xa0spread</mtext><mo>=</mo><mi>s</mi><mtext>\u2009</mtext><mi>P</mi><mtext>\u2009</mtext><mi>N</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Net\xa0proceeds</mtext><mo>=</mo><mi>P</mi><mi>N</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>s</mi><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mtext>Costs</mtext><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Left\xa0on\xa0table</mtext><mo>=</mo><mo stretchy=\\"false\\">(</mo><msub><mi>P</mi><mn>1</mn></msub><mo>\u2212</mo><mi>P</mi><mo stretchy=\\"false\\">)</mo><mi>N</mi></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Gross spread}=s\\\\,P\\\\,N,\\\\quad \\\\text{Net proceeds}=PN(1-s)-\\\\text{Costs},\\\\quad \\\\text{Left on table}=(P_{1}-P)N</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"ipo-underpricing","name":"IPO Underpricing (Initial Return)"},"next":{"slug":"iqr-outlier-fences","name":"IQR Outlier Fences"},"lesson":null,"total":522}')}}]);